fn weekly_template(weekday: Weekday) -> &'static [(&'static str, u32, u32)] {
    match weekday {
        Weekday::Mon | Weekday::Tue | Weekday::Wed | Weekday::Thu => &[
            ("TV1", 6, 18),
            ("NV1", 18, 6),
            ("TV2", 6, 18),
            ("NV2", 18, 6),
            ("TV3", 7, 19),
            ("TM1", 6, 18),
            ("NM1", 18, 6),
        ],
        Weekday::Fri | Weekday::Sat => &[
            ("TV1", 6, 18),
            ("NV1", 18, 6),
            ("TV2", 6, 18),
            ("NV2", 18, 6),
            ("TV3F", 7, 15),
            ("TV3S", 15, 23),
            ("TM1", 6, 18),
            ("NM1", 18, 6),
        ],
        Weekday::Sun => &[
            ("TV1", 6, 18),
            ("NV1", 18, 6),
            ("TV2", 6, 18),
            ("NV2", 18, 6),
            ("TM1", 6, 18),
            ("NM1", 18, 6),
        ],
    }
}

fn station_for(name: &str) -> &'static str {
    match name.as_bytes().get(1) {
        Some(b'M') => "Station 41",
        _ => "Station 40",
    }
}

fn generate_plan(count_mitarbeiters: usize, weeks: usize) -> Plan {
    let base = NaiveDate::from_ymd_opt(2026, 10, 5).unwrap();

    let mut counters: HashMap<Qualifikation, usize> = HashMap::new();
    let mitarbeiters = (0..count_mitarbeiters)
        .map(|idx| {
            let q = if idx % 9 < 5 { Qualifikation::NFS } else { Qualifikation::RS };
            let counter = counters.entry(q).or_insert(0);
            *counter += 1;
            let nr = *counter;
            Mitarbeiter {
                id: format!("mitarbeiter-{idx}"),
                index: idx,
                name: format!("{q:?}{nr}"),
                stammwache: (*["Station 40", "Station 42"].choose(&mut rng()).unwrap()).parse::<String>().unwrap(),
                schichtgruppe: ((nr as i32 - 1) % SCHICHTGRUPPEN) + 1,
                qualifikation: vec![q],
                keine_nacht: rng().random_bool(0.05),
                stellenanteil: ((idx % 7) as i32) - 2,
                is_br: rng().random_bool(0.1)
            }
        })
        .collect::<Vec<_>>();

    let mut schichts: Vec<Schicht> = Vec::new();
    let mut idx = 0usize;
    for w in 0..weeks {
        for d in 0..7 {
            let day = base + Duration::days((w * 7 + d) as i64);
            for (name, start_h, end_h) in weekly_template(day.weekday()) {
                let start = NaiveDateTime::new(day, NaiveTime::from_hms_opt(*start_h, 0, 0).unwrap());
                let end_date = if end_h > start_h { day } else { day + Duration::days(1) };
                let ende = NaiveDateTime::new(end_date, NaiveTime::from_hms_opt(*end_h, 0, 0).unwrap());
                schichts.push(Schicht {
                    id: format!("schicht-{idx}"),
                    index: idx,
                    name: name.to_string(),
                    start,
                    ende,
                    wache: station_for(name).to_string(),
                    qualifikation: vec![Qualifikation::RS, Qualifikation::NFS]
                });
                idx += 1;
            }
        }
    }

    let qualifizierte: Vec<Vec<usize>> = ALL_QUALIFIKATIONEN
        .iter()
        .map(|q| mitarbeiters.iter()
            .filter(|m| m.qualifikation.contains(q))
            .map(|m| m.index)
            .collect())
        .collect();
    let mut naechster = [0; ALL_QUALIFIKATIONEN.len()];
    let mut naechster_mitarbeiter = |q: Qualifikation| {
        let qi = qualifikations_index(q);
        let kandidaten = &qualifizierte[qi];
        if kandidaten.is_empty() {
            None
        } else {
            let index = kandidaten[naechster[qi] % kandidaten.len()];
            naechster[qi] += 1;
            Some(index)
        }
    };

    let mut i = 0;
    let mut schichtzuordnungs: Vec<Schichtzuordnung> = Vec::new();
    for s in &schichts {
        schichtzuordnungs.push(
            Schichtzuordnung {
                id: format!("schichtzuordnung-{i}"),
                schicht_id: s.index,
                qualifikation: s.qualifikation[0].clone(),
                mitarbeiter_idx: naechster_mitarbeiter(s.qualifikation[0])
            }
        );
        i+=1;
        schichtzuordnungs.push(
            Schichtzuordnung {
                id: format!("schichtzuordnung-{i}"),
                schicht_id: s.index,
                qualifikation: s.qualifikation[1].clone(),
                mitarbeiter_idx: naechster_mitarbeiter(s.qualifikation[1])
            }
        );
        i+=1;
    }

    let kandidaten = ALL_QUALIFIKATIONEN
        .iter()
        .map(|q| QualifikationsKandidaten {
            id: format!("kandidaten-{}", qualifikations_index(*q)),
            qualifikation: *q,
            mitarbeiter: mitarbeiters
                .iter()
                .filter(|m| m.qualifikation.contains(q))
                .map(|m| m.index)
                .collect(),
            schichtzuordnungen: schichtzuordnungs
                .iter()
                .enumerate()
                .filter(|(_, sz)| sz.qualifikation == *q)
                .map(|(i, _)| i)
                .collect(),
        })
        .collect::<Vec<_>>();

    Plan::new(mitarbeiters, schichts, schichtzuordnungs, kandidaten)
}
